import './App.css';
import { createBrowserRouter, useSearchParams, RouterProvider } from "react-router-dom";
import { Chance } from 'chance'

const people = [
  'Andrew',
  'Jennie',
  'Stella',
  'Keira',
  'Maud',
  'Leo',
  'Sandra',
  'Malin',
  'Kevin',
  'Ellie',
];

function App() {
  const router = createBrowserRouter([
    {
      path: "*",
      element: <Main />,
    }
  ]);

  return (
    <div className="App">
      <header className="App-header">
        Secret santa
      </header>
      <main className="App-main">
        <RouterProvider router={router} />
      </main>
    </div>
  );
}

const Main = () => {
  const [searchParams, setSearchParams] = useSearchParams();

  const setMakerNumber = (newNumber) => {
    searchParams.set("m", newNumber);
    searchParams.delete("s");
    setSearchParams(Object.fromEntries(searchParams.entries()));
  };

  const makerNumber = searchParams.get("m");
  const displayString = searchParams.get("s");
  if (makerNumber !== null) {
    return <Maker number={makerNumber} setNumber={setMakerNumber} />;
  } else if (displayString !== null) {
    const [number, id] = displayString.split("_");
    return <Display number={number} id={parseInt(id)} />;
  } else {
    return <Base />;
  }

};

const Maker = ({number, setNumber}) => {
  const onNumberChange = (event) => {
    event.preventDefault();
    setNumber(event.target.value);
  };

  return <>
      <input type="text" onChange={onNumberChange} value={number}/>
      <SecretSantaList peopleList={people} number={number}/>
    </>;
};

const combineHash = (p, v) => {
  return ((p * 17) + v) % 65536;
};

const hashString = (str) => {
  var h = 0
  for (var i = 0; i < str.length; ++i) {
    h = combineHash(h, str.charCodeAt(i));
  }
  return h;
};

const shuffleList = (list, number) => {
  const chance = new Chance(...list, number);
  return chance.shuffle(list);
};

const getPersonMapping = (list, number) => {
  const giftOrder = shuffleList(list, number);
  const mapping = {};
  mapping[giftOrder[giftOrder.length - 1]] = giftOrder[0];
  for (var i = 0; i < list.length - 1; ++i) {
    mapping[giftOrder[i]] = giftOrder[i + 1];
  }
  return mapping;
};

const SecretSantaList = ({
  peopleList,
  number
}) => {
  const sortedPeople = [...peopleList];
  sortedPeople.sort();

  return (
    <ul>
      {
        sortedPeople.map(person => (
          <li key={person}>
            <LinkToDisplay
              person={person}
              number={number} />
          </li>
        ))
      }
    </ul>
  );
};

const LinkToDisplay = ({person, number}) => {
  const id = hashString(person);
  const href = `?s=${number}_${id}`;
  return <a
    href={href}
    className='App-link'>
      {person}: {href}
  </a>;
};

const Display = ({number, id}) => {
  const mapping = getPersonMapping(people, number);
  const targetEntry = Object.entries(mapping).find(([person]) => hashString(person) === id);
  if (!targetEntry) {
    return <>Vem fasen är du?</>;
  }
  const [person, targetPerson] = targetEntry;
  return <>Hej {person}! Du ska ge till {targetPerson}!</>;
};

const Base = () => {
  return <>Vem är din secret santa? Högst oklart? ¯\_(ツ)_/¯</>
};

export default App;
